const DEFAULT_DATA={settings:{locationLabel:"Bihar",address:"Donar Road, Darbhanga",homepage:{eyebrow:"PROJECT EXECUTION • TENDER WORK • MANPOWER",title:"Building Work.",accent:"Delivering Trust.",lead:"SS Enterprises is focused on professional execution of contracted and tender-based projects with reliable manpower, disciplined supervision and responsible coordination."},announcement:{enabled:false,title:"",text:"",link:"",linkLabel:"Learn More"},featuredProjectId:"abha",sections:{about:true,services:true,projects:true,team:true,credentials:true,vision:true,gallery:true,contact:true},about:{eyebrow:"ABOUT SS ENTERPRISES",title:"People, projects &",accent:"professional execution.",text:"We take up suitable contracted and tender-based work and build dependable teams to execute it with accountability, coordination and service.",cards:[{title:"Tender Work",text:"Responsible execution of awarded and contracted work with clear coordination."},{title:"Project Execution",text:"Organised manpower, supervision and on-ground coordination for project delivery."},{title:"Skilled Manpower",text:"Building dependable teams suited to the requirements of each project."},{title:"Workforce Expansion",text:"Scalable staffing as project volume and operational requirements increase."}]},services:{eyebrow:"OUR SERVICES",title:"What we",accent:"do best.",text:"Professional services for tender work, project execution, manpower coordination and reliable field support.",cards:[{title:"Tender & Contract Work",text:"Execution support for awarded tenders and contracted assignments."},{title:"Project Manpower",text:"Reliable staffing, supervision and field coordination for active projects."},{title:"Digital Service Projects",text:"Operational support for digital service workflows and citizen-facing projects."}]},contact:{eyebrow:"LET'S WORK TOGETHER",title:"Have a project in mind?",text:"For business enquiries, project discussions and work opportunities, contact SS Enterprises directly.",phone:"+91 73600 25302",whatsapp:"+91 73600 25302",email:"ssenterprisesservice@poton.me",address:"Donar Road, Darbhanga",socials:[{label:"Facebook",url:""},{label:"Instagram",url:""},{label:"YouTube",url:""}]},gallery:[]},projects:[{id:"abha",name:"ABHA Card Project",department:"Health / Digital Health Services",location:"Bihar",status:"ongoing",description:"ABHA Card service work through the existing SS Enterprises digital service workflow.",date:"Active",link:"https://ss-enterprises-abha-app-2026.onrender.com/",photo:"",published:true},{id:"ayushman",name:"Ayushman Card KYC Project",department:"Ayushman Bharat",location:"Bihar",status:"upcoming",description:"Ayushman Card KYC related project supporting field coordination and service delivery as per project requirements.",date:"Upcoming",link:"",photo:"",published:true}],team:[{id:"founder",role:"Founder",name:"Founder",location:"Darbhanga, Bihar",responsibilities:"Overall vision, strategic decisions, business direction and major operations.",photo:"",contact:""},{id:"ceo",role:"CEO & Managing Director",name:"CEO & Managing Director",location:"Darbhanga, Bihar",responsibilities:"Day-to-day operations, project and tender coordination, team management and organisational growth.",photo:"",contact:""},{id:"state-head",role:"State Head",name:"State Head",location:"Bihar",responsibilities:"State-level project coordination, field operations and monitoring of district teams.",photo:"",contact:""},{id:"district-coordinator",role:"District Coordinator",name:"District Coordinator",location:"Darbhanga, Bihar",responsibilities:"District project implementation, field staff coordination and monitoring of assigned work.",photo:"",contact:""}]};
let data=JSON.parse(JSON.stringify(DEFAULT_DATA)),sb=null,currentTab="dashboard",company={profile:null,staff:[],attendance:[],leaves:[],advances:[],promotions:[],payroll:[],expenses:[],income:[],payments:[],users:[],letters:[]},selectedStaffId=null;
const $=id=>document.getElementById(id),esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
const configured=window.SS_CONFIG&&window.SS_CONFIG.SUPABASE_URL&&window.SS_CONFIG.SUPABASE_URL.startsWith("http")&&!window.SS_CONFIG.SUPABASE_URL.includes("PASTE_");
if(configured&&window.supabase)sb=window.supabase.createClient(window.SS_CONFIG.SUPABASE_URL,window.SS_CONFIG.SUPABASE_ANON_KEY);
const today=()=>new Date().toISOString().slice(0,10),monthNow=()=>new Date().toISOString().slice(0,7),money=n=>"₹"+Number(n||0).toLocaleString("en-IN",{maximumFractionDigits:2});
function msg(t,ok=false){if($("saveMsg")){ $("saveMsg").textContent=t;$("saveMsg").className="admin-msg "+(ok?"ok":"");}}
function merge(ds,arr){arr=Array.isArray(arr)?arr:[];return ds.map(d=>{let f=arr.find(x=>x&&x.id===d.id);return f?{...d,...f}:{...d}}).concat(arr.filter(x=>x&&!ds.some(d=>d.id===x.id)))}
function normalise(raw){let s=raw?.settings||{};data={settings:{...DEFAULT_DATA.settings,...s,homepage:{...DEFAULT_DATA.settings.homepage,...s.homepage},announcement:{...DEFAULT_DATA.settings.announcement,...s.announcement},sections:{...DEFAULT_DATA.settings.sections,...s.sections},about:{...DEFAULT_DATA.settings.about,...s.about},services:{...DEFAULT_DATA.settings.services,...s.services},contact:{...DEFAULT_DATA.settings.contact,...s.contact},gallery:Array.isArray(s.gallery)?s.gallery:[]},projects:merge(DEFAULT_DATA.projects,raw?.projects),team:merge(DEFAULT_DATA.team,raw?.team)};data.projects=data.projects.map(p=>({...p,location:"Bihar",status:p.status==="active"?"ongoing":p.status||"upcoming",published:p.published!==false}));data.settings.address="Donar Road, Darbhanga";data.settings.contact.address="Donar Road, Darbhanga";["homepage","about","services","contact"].forEach(k=>{if(!data.settings[k].hi)data.settings[k].hi={}});data.settings.about.cards=(data.settings.about.cards||[]).map(c=>({...c,hi:c.hi||{}}));data.settings.services.cards=(data.settings.services.cards||[]).map(c=>({...c,hi:c.hi||{}}));data.projects.forEach(p=>p.hi=p.hi||{});data.team.forEach(t=>t.hi=t.hi||{})}
function showTab(tab){currentTab=tab;document.querySelectorAll(".tab[data-tab]").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));document.querySelectorAll(".tab-page").forEach(p=>p.classList.toggle("active",p.dataset.page===tab));let titles={dashboard:"Dashboard",projects:"Projects",team:"Leadership & Team",content:"Website Content",controls:"Website Control",gallery:"Gallery / Photos",staff:"Staff Management",attendance:"Attendance",payroll:"Payroll / Salary",leave:"Leave Management",advance:"Staff Advance",promotion:"Promotion / Increment",accounts:"Accounts / Expenses / Income / Payments",users:"Users & Roles",letters:"Offer / Joining Letters",reports:"Reports",collections:"Field Payment Collection",paymentsettings:"Company Payment Settings"};if($("pageTitle"))$("pageTitle").textContent=titles[tab]||"Dashboard";window.scrollTo({top:0,behavior:"smooth"});document.querySelector(".admin-sidebar")?.classList.remove("open")}
function setPath(o,path,v){let p=path.split("."),last=p.pop(),c=o;p.forEach(k=>{if(!c[k]||typeof c[k]!=="object")c[k]={};c=c[k]});c[last]=v}function getPath(o,path){return path.split(".").reduce((x,k)=>x?.[k],o)}
function renderDashboard(){ $("statProjects").textContent=data.projects.length;$("statUpcoming").textContent=data.projects.filter(p=>p.status==="upcoming").length;$("statOngoing").textContent=data.projects.filter(p=>p.status==="ongoing").length;$("statPublished").textContent=data.projects.filter(p=>p.published!==false).length;$("dashStaff").textContent=company.staff.filter(s=>s.status==="active").length;$("dashPresent").textContent=company.attendance.filter(a=>a.attendance_date===today()&&a.status==="present").length;$("dashPayroll").textContent=money(company.payroll.filter(p=>(p.salary_month||"").slice(0,7)===monthNow()).reduce((a,p)=>a+Number(p.net_salary||0),0));$("dashBalance").textContent=money(company.income.reduce((a,x)=>a+Number(x.amount||0),0)-company.expenses.reduce((a,x)=>a+Number(x.amount||0),0));}
function renderProjects(){ $("projectForms").innerHTML=data.projects.map((p,i)=>`<article class="admin-card project-admin-row" data-project-index="${i}"><div class="row-head"><div><span class="status-pill ${esc(p.status)}">${esc(p.status)}</span><h3>${esc(p.name)}</h3></div><div class="row-actions"><button class="mini-btn live-project">${p.status==="upcoming"?"Live / Active":"Set Active"}</button><button class="mini-btn toggle-publish">${p.published!==false?"Unpublish":"Publish"}</button><button class="mini-btn danger delete-project">Delete</button></div></div><div class="project-photo-box">${p.photo?`<img src="${esc(p.photo)}" alt="">`:`<div class="photo-empty">📷<span>No project photo</span></div>`}<label class="upload-btn">Upload Photo<input type="file" class="project-upload" accept="image/*" hidden></label></div><div class="form-grid"><label>Project Name<input data-project="name" value="${esc(p.name)}"></label><label>Department / Client<input data-project="department" value="${esc(p.department)}"></label><label>Work / Project Location<input value="Bihar" disabled></label><label>Status<select data-project="status"><option value="upcoming" ${p.status==="upcoming"?"selected":""}>Upcoming</option><option value="ongoing" ${p.status==="ongoing"?"selected":""}>Ongoing</option><option value="completed" ${p.status==="completed"?"selected":""}>Completed</option></select></label><label>Date / Label<input data-project="date" value="${esc(p.date)}"></label><label>Portal / Project Link<input data-project="link" value="${esc(p.link)}"></label><label class="span-2">Description<textarea data-project="description">${esc(p.description)}</textarea></label></div></article>`).join("")||`<div class="admin-card">No projects yet.</div>`;renderFeatured()}
function renderTeam(){ $("teamForms").innerHTML=data.team.map((t,i)=>`<article class="admin-card team-admin-row" data-team-index="${i}"><div class="row-head"><div><span class="role-admin">${esc(t.role)}</span><h3>${esc(t.name)}</h3></div><button class="mini-btn danger delete-team">Delete Member</button></div><div class="photo-row">${t.photo?`<img class="admin-avatar" src="${esc(t.photo)}" alt="">`:`<div class="admin-avatar placeholder">♙</div>`}<label class="upload-btn">Upload Photo<input type="file" class="team-upload" accept="image/*" hidden></label></div><div class="form-grid"><label>Name<input data-team="name" value="${esc(t.name)}"></label><label>Designation<input data-team="role" value="${esc(t.role)}"></label><label>Location<input data-team="location" value="${esc(t.location)}"></label><label>Contact<input data-team="contact" value="${esc(t.contact)}"></label><label class="span-2">Responsibilities<textarea data-team="responsibilities">${esc(t.responsibilities)}</textarea></label></div></article>`).join("")||`<div class="admin-card">No team members.</div>`}
function renderContent(){document.querySelectorAll("[data-setting]").forEach(e=>e.value=getPath(data.settings,e.dataset.setting)??"");renderCards("aboutCards",data.settings.about.cards,"about");renderCards("serviceCards",data.settings.services.cards,"services");$("socialLinks").innerHTML=(data.settings.contact.socials||[]).map((x,i)=>`<div class="repeat-row social-row" data-social-index="${i}"><label>Platform<input data-social="label" value="${esc(x.label)}"></label><label>URL<input data-social="url" value="${esc(x.url)}"></label><button class="mini-btn danger delete-social">Remove</button></div>`).join("");$("hindiContentBox").innerHTML=`<div class="admin-card"><h3>Hindi Website Content</h3><div class="form-grid"><label>Homepage Title — Hindi<input data-hi-setting="homepage.title" value="${esc(data.settings.homepage.hi?.title)}"></label><label>Homepage Accent — Hindi<input data-hi-setting="homepage.accent" value="${esc(data.settings.homepage.hi?.accent)}"></label><label class="span-2">Homepage Description — Hindi<textarea data-hi-setting="homepage.lead">${esc(data.settings.homepage.hi?.lead)}</textarea></label><label>About Title — Hindi<input data-hi-setting="about.title" value="${esc(data.settings.about.hi?.title)}"></label><label>About Accent — Hindi<input data-hi-setting="about.accent" value="${esc(data.settings.about.hi?.accent)}"></label><label>Services Title — Hindi<input data-hi-setting="services.title" value="${esc(data.settings.services.hi?.title)}"></label><label>Services Accent — Hindi<input data-hi-setting="services.accent" value="${esc(data.settings.services.hi?.accent)}"></label><label>Contact Title — Hindi<input data-hi-setting="contact.title" value="${esc(data.settings.contact.hi?.title)}"></label><label class="span-2">Contact Description — Hindi<textarea data-hi-setting="contact.text">${esc(data.settings.contact.hi?.text)}</textarea></label></div></div>`}
function renderCards(id,arr,type){$(id).innerHTML=(arr||[]).map((c,i)=>`<div class="repeat-row" data-repeat="${type}" data-index="${i}"><div class="repeat-title"><b>${type} ${i+1}</b><button class="mini-btn danger delete-repeat">Remove</button></div><label>Title<input data-repeat-field="title" value="${esc(c.title)}"></label><label>Description<textarea data-repeat-field="text">${esc(c.text)}</textarea></label></div>`).join("")}
function renderControls(){let labels={about:"About Us",services:"Services",projects:"Projects",team:"Leadership & Team",credentials:"Credentials",vision:"Vision",gallery:"Gallery",contact:"Contact"};$("sectionToggles").innerHTML=Object.keys(labels).map(k=>`<label class="toggle-card"><span><b>${labels[k]}</b><small>Section visibility</small></span><input type="checkbox" data-section="${k}" ${data.settings.sections[k]?"checked":""}><i></i></label>`).join("");document.querySelectorAll("[data-announcement]").forEach(e=>e[e.type==="checkbox"?"checked":"value"]=data.settings.announcement[e.dataset.announcement]??"");renderFeatured()}
function renderFeatured(){$("featuredProject").innerHTML=data.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===data.settings.featuredProjectId?"selected":""}>${esc(p.name)} — ${esc(p.status)}</option>`).join("")}
function renderGallery(){$("galleryForms").innerHTML=(data.settings.gallery||[]).map((g,i)=>`<article class="admin-card gallery-row" data-gallery-index="${i}"><div class="gallery-preview">${g.url?`<img src="${esc(g.url)}" alt="">`:`<div>📷 No photo</div>`}</div><label class="upload-btn">📷 Upload Photo<input type="file" class="gallery-upload" accept="image/*" hidden></label><div class="form-grid"><label>Photo URL<input data-gallery="url" value="${esc(g.url)}"></label><label>Caption<input data-gallery="caption" value="${esc(g.caption)}"></label></div><button class="mini-btn danger delete-gallery">Remove Photo</button></article>`).join("")||`<div class="admin-card">No gallery photos yet.</div>`}
async function loadTable(name,order){if(!sb)return[];let q=sb.from(name).select("*");if(order)q=q.order(order,{ascending:false});let r=await q;if(r.error){console.error(name,r.error);return[]}return r.data||[]}
async function loadCompany(){company.profile=(await sb.from("company_profile").select("*").eq("id",1).maybeSingle()).data||{id:1,company_name:"SS ENTERPRISES",address:"Donar Road, Darbhanga",phone:"+91 73600 25302",email:"ssenterprisesservice@poton.me",logo_url:"",signature_url:"",stamp_url:""};company.staff=await loadTable("staff","created_at");company.attendance=await loadTable("attendance","attendance_date");company.leaves=await loadTable("leaves","created_at");company.advances=await loadTable("staff_advances","advance_date");company.promotions=await loadTable("promotions","effective_date");company.payroll=await loadTable("payroll","salary_month");company.expenses=await loadTable("expenses","expense_date");company.income=await loadTable("income","income_date");company.payments=await loadTable("payments","payment_date");company.users=await loadTable("app_users","created_at");company.letters=await loadTable("letters","created_at");renderCompany()}
function staffName(id){return company.staff.find(s=>s.id===id)?.full_name||"Unknown"}
function staffOptions(selected=""){return `<option value="">Select Staff</option>`+company.staff.filter(s=>s.status!=="left").map(s=>`<option value="${s.id}" ${s.id===selected?"selected":""}>${esc(s.full_name)} — ${esc(s.designation)}</option>`).join("")}
function renderStaff(){let q=(($("staffSearch")?.value)||"").toLowerCase(),f=$("staffStatusFilter")?.value||"";let arr=company.staff.filter(s=>(!q||`${s.full_name} ${s.designation} ${s.phone} ${s.employee_code||""}`.toLowerCase().includes(q))&&(!f||s.status===f));$("staffTable").innerHTML=arr.map(s=>`<tr><td><b>${esc(s.full_name)}</b><br><small>${esc(s.employee_code||"")}</small></td><td>${esc(s.designation)}</td><td>${esc(s.phone)}</td><td>${esc(s.joining_date||"")}</td><td>${money(s.salary)}</td><td><span class="status-dot">${esc(s.status)}</span></td><td><button class="module-btn ghost edit-staff" data-id="${s.id}">Edit</button> <button class="module-btn primary idcard-staff" data-id="${s.id}">ID Card</button> <button class="module-btn danger delete-staff" data-id="${s.id}">Delete</button></td></tr>`).join("")||`<tr><td colspan="7">No staff found.</td></tr>`}
function newEmployeeCode(){
  // Simple sequential codes: EMP001, EMP002, EMP003...
  let max=0;
  company.staff.forEach(s=>{let m=String(s.employee_code||"").trim().toUpperCase().match(/^EMP(\d+)$/);if(m)max=Math.max(max,Number(m[1]||0))});
  return `EMP${String(max+1).padStart(3,"0")}`;
}
function staffAddress(s={}){return String(s.address??"").trim()||String(s.employee_address??"").trim()||""}
function staffForm(s={}){let basic=Number(s.basic_salary??s.salary??0),ta=Number(s.ta_travel||0),da=Number(s.da_daily||0),rent=Number(s.rent_allowance||0),other=Number(s.other_allowance||0);let gross=basic+ta+da+rent+other;let code=s.employee_code||newEmployeeCode();return `<div class="module-toolbar"><div><h3>${s.id?"Edit Staff":"Add Staff"}</h3><p class="admin-muted">One Employee ID is shared by Staff, Offer/Joining Letter, ID Card and QR profile.</p></div><button class="module-btn ghost close-form">Close</button></div><div class="module-form"><label>Employee Code<input id="sf_code" value="${esc(code)}" placeholder="EMP001" autocomplete="off"><small class="admin-muted">You can enter your own code, e.g. EMP001, EMP002, EMP003.</small></label><label>Full Name<input id="sf_name" value="${esc(s.full_name)}"></label><label>Father Name<input id="sf_father" value="${esc(s.father_name)}"></label><label>Email<input id="sf_email" type="email" value="${esc(s.email)}"></label><label>Phone<input id="sf_phone" value="${esc(s.phone)}"></label><label>Designation<input id="sf_designation" value="${esc(s.designation||"Staff")}"></label><label>Department<input id="sf_department" value="${esc(s.department)}"></label><label>Joining Date<input id="sf_joining" type="date" value="${esc(s.joining_date)}"></label><label>Employee Photo URL<input id="sf_photo" value="${esc(s.photo_url||"")}" placeholder="Supabase/public image URL"></label><label>Employee Signature URL<input id="sf_signature" value="${esc(s.employee_signature_url||"")}" placeholder="Employee signature image URL"></label><label class="upload-btn staff-sign-upload">Upload Employee Signature<input id="sf_signature_file" type="file" accept="image/*" hidden></label><label>Basic Salary<input id="sf_basic" type="number" value="${basic}"></label><label>TA / Travel Allowance<input id="sf_ta" type="number" value="${ta}"></label><label>DA / Daily Allowance<input id="sf_da" type="number" value="${da}"></label><label>Rent / HRA Allowance<input id="sf_rent" type="number" value="${rent}"></label><label>Other Allowance<input id="sf_other" type="number" value="${other}"></label><label>Gross Monthly Salary<input id="sf_salary" type="number" value="${gross}" readonly></label><label>Status<select id="sf_status"><option ${s.status==="active"||!s.status?"selected":""}>active</option><option ${s.status==="inactive"?"selected":""}>inactive</option><option ${s.status==="left"?"selected":""}>left</option></select></label><label>Bank Name<input id="sf_bank" value="${esc(s.bank_name)}"></label><label>Account Number<input id="sf_account" value="${esc(s.account_number)}"></label><label>IFSC<input id="sf_ifsc" value="${esc(s.ifsc)}"></label><label class="full">Employee Address<textarea id="sf_address" name="employee_address" autocomplete="street-address" placeholder="Enter employee full address">${esc(staffAddress(s))}</textarea></label><label class="full">Notes<textarea id="sf_notes">${esc(s.notes)}</textarea></label></div><div class="salary-summary-grid"><div><span>Gross Monthly</span><b id="sf_gross_preview">${money(gross)}</b></div><div><span>Annual CTC</span><b id="sf_annual_preview">${money(gross*12)}</b></div></div><button class="module-btn primary save-staff" data-id="${s.id||""}">Save Staff</button>`}

async function saveStaff(id){let basic=Number($("sf_basic").value||0),ta=Number($("sf_ta").value||0),da=Number($("sf_da").value||0),rent=Number($("sf_rent").value||0),other=Number($("sf_other").value||0),gross=basic+ta+da+rent+other;let code=$("sf_code").value.trim().toUpperCase()||newEmployeeCode();if(!/^EMP\d{3,}$/.test(code))return msg("Employee Code should be like EMP001, EMP002 or EMP003.");let obj={employee_code:code,full_name:$("sf_name").value.trim(),father_name:$("sf_father").value,email:$("sf_email").value.trim(),phone:$("sf_phone").value,designation:$("sf_designation").value,department:$("sf_department").value,location:"Bihar",joining_date:$("sf_joining").value||null,photo_url:$("sf_photo").value.trim(),employee_signature_url:$("sf_signature").value.trim(),salary:gross,basic_salary:basic,ta_travel:ta,da_daily:da,rent_allowance:rent,other_allowance:other,status:$("sf_status").value,bank_name:$("sf_bank").value,account_number:$("sf_account").value,ifsc:$("sf_ifsc").value,address:$("sf_address").value,notes:$("sf_notes").value};obj.address=String(obj.address||"").trim();if(!obj.full_name)return msg("Staff name is required.");let duplicate=company.staff.find(x=>x.employee_code===code&&x.id!==id);if(duplicate)return msg("Employee ID already exists. Please edit the staff record instead.");let r=id?await sb.from("staff").update(obj).eq("id",id):await sb.from("staff").insert(obj);if(r.error)return msg(r.error.message);$("staffFormBox").hidden=true;await loadCompany();msg(`Staff saved. Employee ID ${code} is shared by the Offer Letter and ID Card.`,true)}

function renderAttendance(){let d=$("attendanceDate").value||today();$("attendanceStaff").innerHTML=`<option value="">All Staff</option>`+company.staff.map(s=>`<option value="${s.id}">${esc(s.full_name)}</option>`).join("");let sid=$("attendanceStaff").value;let arr=company.staff.filter(s=>s.status!=="left"&&(!sid||s.id===sid)).map(s=>({staff:s,a:company.attendance.find(a=>a.staff_id===s.id&&a.attendance_date===d)}));$("attendanceTable").innerHTML=arr.map(x=>`<tr><td>${esc(x.staff.full_name)}</td><td><select class="att-status" data-staff="${x.staff.id}"><option value="present" ${x.a?.status==="present"||!x.a?"selected":""}>Present</option><option value="absent" ${x.a?.status==="absent"?"selected":""}>Absent</option><option value="half_day" ${x.a?.status==="half_day"?"selected":""}>Half Day</option><option value="leave" ${x.a?.status==="leave"?"selected":""}>Leave</option></select></td><td><input type="time" class="att-in" data-staff="${x.staff.id}" value="${x.a?.check_in?new Date(x.a.check_in).toTimeString().slice(0,5):""}"></td><td><input type="time" class="att-out" data-staff="${x.staff.id}" value="${x.a?.check_out?new Date(x.a.check_out).toTimeString().slice(0,5):""}"></td><td><input class="att-location" data-staff="${x.staff.id}" value="${esc(x.a?.location||"")}" placeholder="Site / location"></td><td><button class="module-btn primary save-att" data-staff="${x.staff.id}">Save</button></td></tr>`).join("")}
async function saveAttendance(staffId){let d=$("attendanceDate").value||today(),status=document.querySelector(`.att-status[data-staff="${staffId}"]`).value,ti=document.querySelector(`.att-in[data-staff="${staffId}"]`).value,to=document.querySelector(`.att-out[data-staff="${staffId}"]`).value,loc=document.querySelector(`.att-location[data-staff="${staffId}"]`).value;let obj={staff_id:staffId,attendance_date:d,status,check_in:ti?`${d}T${ti}:00`:null,check_out:to?`${d}T${to}:00`:null,location:loc};let old=company.attendance.find(a=>a.staff_id===staffId&&a.attendance_date===d);let r=old?await sb.from("attendance").update(obj).eq("id",old.id):await sb.from("attendance").insert(obj);if(r.error)msg(r.error.message);else{await loadCompany();showTab("attendance");msg("Attendance saved.",true)}}
function renderPayroll(){let m=$("payrollMonth").value||monthNow(),sid=$("payrollStaff").value;$("payrollStaff").innerHTML=`<option value="">All Staff</option>`+company.staff.map(s=>`<option value="${s.id}" ${s.id===sid?"selected":""}>${esc(s.full_name)}</option>`).join("");let arr=company.payroll.filter(p=>(p.salary_month||"").slice(0,7)===m&&(!sid||p.staff_id===sid));let sums=arr.reduce((a,p)=>{a.basic+=Number(p.basic_salary||0);a.allowance+=Number(p.ta_travel||0)+Number(p.da_daily||0)+Number(p.rent_allowance||0)+Number(p.other_allowance||0);a.ot+=Number(p.overtime||0);a.ded+=Number(p.deduction||0);a.adv+=Number(p.advance_deduction||0);a.net+=Number(p.net_salary||0);return a},{basic:0,allowance:0,ot:0,ded:0,adv:0,net:0});["Basic","Allowance","Overtime","Deduction","Advance","Net"].forEach((k,i)=>{let id=["sumBasic","sumAllowance","sumOvertime","sumDeduction","sumAdvance","sumNet"][i];if($(id))$(id).textContent=money(Object.values(sums)[i])});$("payrollTable").innerHTML=arr.map(p=>`<tr><td><b>${esc(staffName(p.staff_id))}</b></td><td>${money(p.basic_salary)}</td><td>${money(p.ta_travel||0)}</td><td>${money(p.da_daily||0)}</td><td>${money(p.rent_allowance||0)}</td><td>${money(p.other_allowance||0)}</td><td>${money(p.overtime)}</td><td>${money(p.deduction)}</td><td>${money(p.advance_deduction)}</td><td><b>${money(p.net_salary)}</b></td><td>${esc(p.status)}</td><td><button class="module-btn ghost print-one-slip" data-id="${p.id}">Slip</button></td></tr>`).join("")||`<tr><td colspan="12">No payroll for ${m}. Click Generate / Update Month.</td></tr>`}
async function generatePayroll(){let m=$("payrollMonth").value||monthNow(),first=`${m}-01`;for(const s of company.staff.filter(x=>x.status==="active")){let basic=Number(s.basic_salary??s.salary??0),ta=Number(s.ta_travel||0),da=Number(s.da_daily||0),rent=Number(s.rent_allowance||0),other=Number(s.other_allowance||0),adv=company.advances.filter(a=>a.staff_id===s.id&&a.status==="given"&&String(a.advance_date).slice(0,7)===m).reduce((a,x)=>a+Number(x.amount||0),0),old=company.payroll.find(p=>p.staff_id===s.id&&p.salary_month===first),ot=Number(old?.overtime||0),ded=Number(old?.deduction||0),advance=Number(old?.advance_deduction??adv),gross=basic+ta+da+rent+other,net=gross+ot-ded-advance,obj={staff_id:s.id,salary_month:first,basic_salary:basic,ta_travel:ta,da_daily:da,rent_allowance:rent,other_allowance:other,allowance:ta+da+rent+other,overtime:ot,deduction:ded,advance_deduction:advance,net_salary:net,status:old?.status||"draft",payment_date:old?.payment_date||null,payment_method:old?.payment_method||"",notes:old?.notes||""};old?await sb.from("payroll").update(obj).eq("id",old.id):await sb.from("payroll").insert(obj)}await loadCompany();showTab("payroll");msg("Payroll generated/updated with complete salary breakup.",true)}
