function renderPaymentQR(){let x=paymentSettings(),box=$("paymentQRPreview");if(!box)return;let upi=(x.upi_id||"").trim();if(!upi){box.innerHTML="<b>QR preview:</b> पहले Company UPI ID भरकर Save करें।";return}let uri=`upi://pay?pa=${encodeURIComponent(upi)}&pn=${encodeURIComponent(x.display_name||"SS Enterprises")}&cu=INR`;let qr="https://api.qrserver.com/v1/create-qr-code/?size=220x220&data="+encodeURIComponent(uri);box.innerHTML=`<div style="text-align:center;padding:18px"><h3>${esc(x.display_name||"SS Enterprises")}</h3><img src="${qr}" alt="Company UPI QR" style="max-width:220px;width:100%;background:#fff;padding:10px;border-radius:12px"><p><b>Official Company Payment QR</b><br>${esc(upi)}<br><small>${esc(x.payment_note||"")}</small></p></div>`}
function collectionForm(){let b=$("collectionFormBox");b.innerHTML=`<h3>New Field Collection</h3><div class="module-form"><label>Customer Name<input id="cf_customer" required></label><label>Mobile Number<input id="cf_mobile"></label><label>Address<input id="cf_address"></label><label>Service / Purpose<input id="cf_service"></label><label>Amount (₹)<input id="cf_amount" type="number" min="1" required></label><label>Collected By<select id="cf_staff">${staffOptions()}</select></label><label>Payment Mode<select id="cf_mode"><option>UPI</option><option>Cash</option><option>Bank Transfer</option></select></label><label>Transaction / UTR<input id="cf_ref"></label><label class="wide">Remarks<input id="cf_note"></label></div><button class="module-btn primary save-collection">Save Collection & Generate Receipt</button>`;b.hidden=false}
function renderCollections(){let rows=company.collections||[],todayRows=rows.filter(x=>x.collection_date===today()),month=monthNow();if($("colToday"))$("colToday").textContent=money(todayRows.reduce((a,x)=>a+Number(x.amount||0),0));if($("colMonth"))$("colMonth").textContent=money(rows.filter(x=>String(x.collection_date||"").startsWith(month)).reduce((a,x)=>a+Number(x.amount||0),0));if($("colCount"))$("colCount").textContent=rows.length;let tb=$("collectionTable");if(tb)tb.innerHTML=rows.slice().sort((a,b)=>String(b.collection_date).localeCompare(String(a.collection_date))).map(x=>`<tr><td>${esc(x.receipt_no||"")}</td><td>${esc(x.collection_date||"")}</td><td>${esc(x.customer_name||"")}</td><td>${esc(x.service_name||"")}</td><td>${money(x.amount)}</td><td>${esc(staffName(x.staff_id))}</td><td>${esc(x.payment_mode||"")}</td><td><button class="module-btn ghost view-collection" data-id="${x.id}">Receipt</button></td></tr>`).join("")||'<tr><td colspan="8">No collection records yet.</td></tr>'}
function showCollectionReceipt(id){let x=(company.collections||[]).find(z=>z.id===id);if(!x)return;let p=paymentSettings(),b=$("collectionReceipt");b.innerHTML=`<div style="max-width:760px;margin:auto;border:2px solid #d4a637;padding:24px;border-radius:16px;background:#fff"><div style="display:flex;justify-content:space-between;gap:20px"><div><h2 style="margin:0">${esc(p.display_name||"SS Enterprises")}</h2><p>Professional Payment Collection Receipt</p></div><div><b>${esc(x.receipt_no)}</b><br>${esc(x.collection_date)}</div></div><hr><p><b>Customer:</b> ${esc(x.customer_name)}<br><b>Mobile:</b> ${esc(x.mobile||"—")}<br><b>Address:</b> ${esc(x.address||"—")}</p><p><b>Service:</b> ${esc(x.service_name||"—")}<br><b>Collected By:</b> ${esc(staffName(x.staff_id))}<br><b>Employee Code:</b> ${esc((company.staff.find(s=>s.id===x.staff_id)||{}).employee_code||"—")}</p><h2 style="text-align:right">Amount Received: ${money(x.amount)}</h2><p><b>Mode:</b> ${esc(x.payment_mode)} &nbsp; <b>Reference:</b> ${esc(x.reference||"—")}</p><p>${esc(x.remarks||"")}</p><hr><small>This is a computer-generated collection receipt of ${esc(p.display_name||"SS Enterprises")}.</small></div>`;b.hidden=false;b.scrollIntoView({behavior:"smooth"})}
async function saveCollection(){let amount=Number($("cf_amount").value||0);if(!$("cf_customer").value.trim()||amount<=0)return msg("Customer name and valid amount are required.");let rec={receipt_no:"SSE-"+today().replaceAll("-","")+"-"+String(Date.now()).slice(-5),collection_date:today(),customer_name:$("cf_customer").value.trim(),mobile:$("cf_mobile").value.trim(),address:$("cf_address").value.trim(),service_name:$("cf_service").value.trim(),amount,staff_id:$("cf_staff").value||null,payment_mode:$("cf_mode").value,reference:$("cf_ref").value.trim(),remarks:$("cf_note").value.trim()};let r=await sb.from("field_collections").insert(rec);if(r.error)return msg(r.error.message);await loadCompany();msg("Collection saved and receipt generated.",true);let saved=(company.collections||[]).find(x=>x.receipt_no===rec.receipt_no);if(saved)showCollectionReceipt(saved.id)}
async function savePaymentSettings(){let rec={id:1,display_name:$("ps_name").value.trim()||"SS Enterprises",account_type:$("ps_type").value,bank_name:$("ps_bank").value.trim(),account_number:$("ps_account").value.trim(),ifsc_code:$("ps_ifsc").value.trim(),upi_id:$("ps_upi").value.trim(),payment_note:$("ps_note").value.trim()};let r=await sb.from("company_payment_settings").upsert(rec,{onConflict:"id"});if(r.error)return msg(r.error.message);company.paymentSettings=rec;msg("Company payment settings saved.",true);renderPaymentQR()}

async function transferSalary(id){
  const p=company.payroll.find(x=>x.id===id);
  if(!p)return;
  const s=company.staff.find(x=>x.id===p.staff_id)||{};
  const amount=Number(p.net_salary||0);
  if(amount<=0)return msg("Net salary must be greater than ₹0 before transfer.");
  if(!s.account_number||!s.ifsc)return msg("Employee bank Account Number and IFSC are required before salary transfer.");
  if(p.status==="paid")return msg("This salary is already marked as paid.");
  if(!confirm(`Record salary transfer of ${money(amount)} to ${s.full_name||"employee"}?`))return;
  const ref=`SAL-${String(p.salary_month||today()).slice(0,7).replace("-","")}-${String(s.employee_code||s.id).slice(-6).toUpperCase()}-${Date.now().toString().slice(-5)}`;
  const pay={payment_date:today(),payment_type:"staff_salary",party_name:s.full_name||"Staff Salary",amount,direction:"out",method:"Bank Transfer",reference:ref,notes:`Salary for ${String(p.salary_month||today()).slice(0,7)} | Account: ${s.account_number} | IFSC: ${s.ifsc}`};
  const r=await sb.from("payments").insert(pay);
  if(r.error)return msg("Salary transfer record failed: "+r.error.message);
  const u=await sb.from("payroll").update({status:"paid",payment_date:today(),payment_method:"Bank Transfer",notes:ref}).eq("id",id);
  if(u.error)return msg("Payment recorded, but payroll status update failed: "+u.error.message);
  await loadCompany();
  msg(`Salary transfer recorded for ${s.full_name}. Reference: ${ref}`,true);
}

function renderSimpleTables(){ $("leaveTable").innerHTML=company.leaves.map(x=>`<tr><td>${esc(staffName(x.staff_id))}</td><td>${x.from_date} → ${x.to_date}</td><td>${esc(x.leave_type)}</td><td>${esc(x.reason)}</td><td>${esc(x.status)}</td><td><button class="module-btn ghost leave-approve" data-id="${x.id}" data-status="approved">Approve</button> <button class="module-btn danger leave-approve" data-id="${x.id}" data-status="rejected">Reject</button></td></tr>`).join("")||`<tr><td colspan="6">No leave records.</td></tr>`;$("advanceTable").innerHTML=company.advances.map(x=>`<tr><td>${esc(staffName(x.staff_id))}</td><td>${x.advance_date}</td><td>${money(x.amount)}</td><td>${esc(x.reason)}</td><td>${esc(x.status)}</td><td><button class="module-btn ghost advance-recovered" data-id="${x.id}">Recovered</button></td></tr>`).join("")||`<tr><td colspan="6">No advances.</td></tr>`;$("promotionTable").innerHTML=company.promotions.map(x=>`<tr><td>${esc(staffName(x.staff_id))}</td><td>${x.effective_date}</td><td>${esc(x.old_designation)} / ${money(x.old_salary)}</td><td>${esc(x.new_designation)}</td><td>${money(x.new_salary)}</td><td>${esc(x.reason)}</td></tr>`).join("")||`<tr><td colspan="6">No promotions.</td></tr>`;let rows=[...company.income.map(x=>({d:x.income_date,t:"Income",desc:x.description||x.source,a:x.amount,m:x.payment_method,r:x.reference})),...company.expenses.map(x=>({d:x.expense_date,t:"Expense",desc:x.description||x.category,a:x.amount,m:x.payment_method,r:x.reference})),...company.payments.map(x=>({d:x.payment_date,t:x.direction==="in"?"Payment In":"Payment Out",desc:x.party_name,a:x.amount,m:x.method,r:x.reference}))].sort((a,b)=>String(b.d).localeCompare(String(a.d)));$("accountsTable").innerHTML=rows.map(x=>`<tr><td>${x.d}</td><td>${x.t}</td><td>${esc(x.desc)}</td><td>${money(x.a)}</td><td>${esc(x.m)}</td><td>${esc(x.r)}</td></tr>`).join("")||`<tr><td colspan="6">No transactions.</td></tr>`}
function formBox(type){let b=$(type+"FormBox");if(type==="leave")b.innerHTML=`<div class="module-form"><label>Staff<select id="lf_staff">${staffOptions()}</select></label><label>From<input id="lf_from" type="date" value="${today()}"></label><label>To<input id="lf_to" type="date" value="${today()}"></label><label>Type<select id="lf_type"><option>Casual Leave</option><option>Sick Leave</option><option>Earned Leave</option><option>Other</option></select></label><label class="wide">Reason<input id="lf_reason"></label></div><button class="module-btn primary form-save-leave">Save Leave</button>`;if(type==="advance")b.innerHTML=`<div class="module-form"><label>Staff<select id="ad_staff">${staffOptions()}</select></label><label>Date<input id="ad_date" type="date" value="${today()}"></label><label>Amount<input id="ad_amount" type="number"></label><label class="wide">Reason<input id="ad_reason"></label></div><button class="module-btn primary form-save-advance">Save Advance</button>`;if(type==="promotion")b.innerHTML=`<div class="module-form"><label>Staff<select id="pr_staff">${staffOptions()}</select></label><label>Effective Date<input id="pr_date" type="date" value="${today()}"></label><label>New Designation<input id="pr_role"></label><label>New Salary<input id="pr_salary" type="number"></label><label class="wide">Reason<input id="pr_reason"></label></div><button class="module-btn primary form-save-promotion">Save Promotion</button>`;if(type==="accounts")b.innerHTML=`<div class="module-form"><label>Date<input id="ac_date" type="date" value="${today()}"></label><label>Amount<input id="ac_amount" type="number"></label><label>Payment Method<select id="ac_method"><option>Cash</option><option>Bank</option><option>UPI</option><option>Other</option></select></label><label>Category / Source<input id="ac_category"></label><label class="wide">Description / Party<input id="ac_desc"></label><label>Reference<input id="ac_ref"></label></div><button class="module-btn primary form-save-account">Save</button>`;b.hidden=false}
async function saveForm(type){let r;if(type==="leave")r=await sb.from("leaves").insert({staff_id:$("lf_staff").value,from_date:$("lf_from").value,to_date:$("lf_to").value,leave_type:$("lf_type").value,reason:$("lf_reason").value});if(type==="advance")r=await sb.from("staff_advances").insert({staff_id:$("ad_staff").value,advance_date:$("ad_date").value,amount:Number($("ad_amount").value||0),reason:$("ad_reason").value});if(type==="promotion"){let s=company.staff.find(x=>x.id===$("pr_staff").value);r=await sb.from("promotions").insert({staff_id:s.id,effective_date:$("pr_date").value,old_designation:s.designation,new_designation:$("pr_role").value,old_salary:s.salary,new_salary:Number($("pr_salary").value||0),reason:$("pr_reason").value});if(!r.error)await sb.from("staff").update({designation:$("pr_role").value,salary:Number($("pr_salary").value||0)}).eq("id",s.id)}if(type==="accounts"){let isExpense=$("accountsFormBox").dataset.mode==="expense",isIncome=$("accountsFormBox").dataset.mode==="income";let base={expense_date:$("ac_date").value,category:$("ac_category").value,description:$("ac_desc").value,amount:Number($("ac_amount").value||0),payment_method:$("ac_method").value,reference:$("ac_ref").value};if(isExpense)r=await sb.from("expenses").insert(base);else if(isIncome)r=await sb.from("income").insert({income_date:base.expense_date,source:base.category,description:base.description,amount:base.amount,payment_method:base.payment_method,reference:base.reference});else r=await sb.from("payments").insert({payment_date:base.expense_date,payment_type:"other",party_name:base.description,amount:base.amount,direction:"out",method:base.payment_method,reference:base.reference})}if(r?.error)msg(r.error.message);else{await loadCompany();msg("Saved successfully.",true)}}
