function letterHtml(){let s=company.staff.find(x=>x.id===$("letterStaff").value);if(!s)return"";let p=company.profile||{},type=$("letterType").value,offer=type==="offer",date=$("letterDate").value||today(),subject=$("letterSubject").value||(offer?"Job Offer Letter":"Joining Letter"),num=$("letterNumber").value||`SSE/OFF/${date.slice(0,4)}/${String(s.employee_code||s.id).slice(-3)}`,employeeAddress=staffAddress(s),basic=Number(s.basic_salary||0),ta=Number(s.ta_travel||0),da=Number(s.da_daily||0),rent=Number(s.rent_allowance||0),other=Number(s.other_allowance||0);if(basic+ta+da+rent+other<=0&&Number(s.salary||0)>0)basic=Number(s.salary);let gross=basic+ta+da+rent+other,annual=gross*12,logo=p.logo_url||"logo.png";let body=offer?`With reference to your recent interview and subsequent discussions with us, we are pleased to inform you that you have been selected for employment with <b>${esc(p.company_name||"SS ENTERPRISES")}</b> for the position of <b>${esc(s.designation)}</b>.`: `This is to confirm that <b>${esc(s.full_name)}</b> has joined <b>${esc(p.company_name||"SS ENTERPRISES")}</b> as <b>${esc(s.designation)}</b>. We welcome you and wish you success in your responsibilities.`;return `<div class="letter-document"><section class="letter-page"><div class="letter-watermark">SS ENTERPRISES</div><div class="letter-head"><img src="${esc(logo)}" onerror="this.src='logo.png'"><div><h2>${esc(p.company_name||"SS ENTERPRISES")}</h2><div>${esc(p.address||"Donar Road, Darbhanga")}</div><div>${esc(p.phone||"")} ${esc(p.email||"")}</div><small>AAPKI SEVA MEIN SADA SAMARPIT</small></div></div><div class="letter-meta"><b>Ref. No: ${esc(num)}</b><b>Date: ${esc(date)}</b></div><div class="letter-to"><b>To,</b><br>Mr. / Ms. ${esc(s.full_name)}<br>Address: ${esc(employeeAddress||"—")}</div><h2 class="letter-subject">${esc(subject)}</h2><p>Dear <b>${esc(s.full_name)}</b>,</p><p>${body}</p><p>The details and terms of this ${offer?"provisional offer":"joining confirmation"} are outlined below:</p><div class="letter-detail-box"><p><b>Designation:</b> ${esc(s.designation)}</p><p><b>Department:</b> ${esc(s.department||"—")}</p><p><b>Total Emolument (CTC):</b> ${money(annual)} /- per annum</p><p><b>Probation Period:</b> 6 Months from the date of joining</p><p><b>Joining Date:</b> ${esc(s.joining_date||"On or before mutually agreed date")}</p></div><p>Upon successful completion of all joining formalities and submission of all required credentials, you will be placed as per company terms. A detailed Appointment Letter containing complete terms and conditions of employment will be issued upon formal joining.</p><div class="letter-note"><b>Note:</b> Please submit self-attested educational certificates, identity proof, address proof and 4 passport size photographs within 7 days of receiving this letter or at the time of joining.</div><p>Please sign and retain the duplicate copy of this letter as a token of your acceptance.</p><p>We look forward to welcoming you to ${esc(p.company_name||"SS Enterprises")} and wish you a successful career with us.</p><div class="letter-sign three-sign"><div class="sign-box employee-sign">${s.employee_signature_url?`<img src="${esc(s.employee_signature_url)}" class="employee-sign-img"><br>`:""}<div class="sign-line"></div><b>Employee Signature</b><small>${esc(s.full_name)}</small></div><div class="sign-box">${p.stamp_url?`<img src="${esc(p.stamp_url)}" class="stamp-img"><br>`:""}<b>Company Stamp / Mohar</b></div><div class="sign-box">${p.signature_url?`<img src="${esc(p.signature_url)}" class="authorized-sign-img"><br>`:""}<b>${esc(offer?(p.offer_footer||"For SS Enterprises"):(p.joining_footer||"For SS Enterprises"))}</b><br>Authorised Signatory</div></div><div class="letter-footer">${esc(p.company_name||"SS Enterprises")} | Corporate Office: ${esc(p.address||"Donar Road, Darbhanga")} | Contact: ${esc(p.phone||"")} | Email: ${esc(p.email||"")}</div></section><section class="letter-page salary-page"><div class="letter-watermark">SS ENTERPRISES</div><div class="letter-head"><img src="${esc(logo)}" onerror="this.src='logo.png'"><div><h2>${esc(p.company_name||"SS ENTERPRISES")}</h2><small>SALARY STRUCTURE / COMPENSATION DETAILS</small></div></div><div class="letter-meta"><b>Employee: ${esc(s.full_name)}</b><b>Employee Code: ${esc(s.employee_code||"—")}</b></div><h2 class="letter-subject">Salary Component</h2><table class="salary-breakup salary-breakup-final"><thead><tr><th>Salary Component</th><th>Monthly Amount</th><th>Annual Amount</th></tr></thead><tbody><tr><td>Basic Salary</td><td>${money(basic)} /-</td><td>${money(basic*12)} /-</td></tr><tr><td>HRA – House Rent Allowance</td><td>${money(rent)} /-</td><td>${money(rent*12)} /-</td></tr><tr><td>TA / Travel Allowance</td><td>${money(ta)} /-</td><td>${money(ta*12)} /-</td></tr><tr><td>DA / Daily Allowance</td><td>${money(da)} /-</td><td>${money(da*12)} /-</td></tr><tr><td>Other Allowance</td><td>${money(other)} /-</td><td>${money(other*12)} /-</td></tr><tr class="salary-total"><th>Total Monthly Gross Salary</th><th>${money(gross)} /-</th><th>${money(annual)} /-</th></tr></tbody></table><p class="annual-summary"><b>Designation:</b> ${esc(s.designation)} &nbsp; <b>Department:</b> ${esc(s.department||"—")} &nbsp; <b>Joining Date:</b> ${esc(s.joining_date||"—")}</p><div class="letter-note"><b>Important:</b> Salary figures are generated from the approved salary components stored for this employee in the Admin Panel. Salary and allowances are not printed on the Identity Card.</div><div class="letter-sign two-sign"><div class="sign-box">${p.stamp_url?`<img src="${esc(p.stamp_url)}" class="stamp-img"><br>`:""}<b>Company Stamp / Mohar</b></div><div class="sign-box">${p.signature_url?`<img src="${esc(p.signature_url)}" class="authorized-sign-img"><br>`:""}<b>Authorised Signatory</b></div></div><div class="letter-footer">${esc(p.company_name||"SS Enterprises")} | Corporate Office: ${esc(p.address||"Donar Road, Darbhanga")} | Contact: ${esc(p.phone||"")} | Email: ${esc(p.email||"")}</div></section></div>`}

function publicEmployeeUrl(code){return new URL(`employee.html?employee=${encodeURIComponent(code)}`,window.location.href).href}
function idCardHtml(s){let p=company.profile||{},code=s.employee_code||"",logo=p.logo_url||"logo.png",photo=s.photo_url||"",qrId=`qr-${String(s.id).replace(/[^a-z0-9]/gi,"")}`;return `<div class="id-sheet"><div class="id-card id-front"><div class="id-top"><img class="id-logo" src="${esc(logo)}" onerror="this.src='logo.png'"><div><div class="id-company">${esc(p.company_name||"SS ENTERPRISES")}</div><div class="id-tag">SS ENTERPRISES EMPLOYEE IDENTITY CARD</div></div></div><div class="id-main"><div>${photo?`<img class="id-photo" src="${esc(photo)}" alt="Employee photo">`:`<div class="id-photo id-photo-empty">PHOTO</div>`}</div><div class="id-info"><h3>${esc(s.full_name)}</h3><p><b>ID:</b> ${esc(code)}</p><p><b>Designation:</b> ${esc(s.designation||"Staff")}</p><p><b>Department:</b> ${esc(s.department||"—")}</p><p><b>Joining:</b> ${esc(s.joining_date||"—")}</p><span class="id-abha">${esc(s.department||s.designation||"SS Enterprises Project")}</span></div><div><div class="id-qr" id="${qrId}"></div><div class="id-project">Scan QR for employee + company details</div></div></div><div class="id-bottom"><div><small>${esc(p.address||"Donar Road, Darbhanga")}<br>Company: ${esc(p.phone||"")}<br>Mobile: ${esc(s.phone||"—")} · ${esc(code)}</small></div><div><small>Joining Date<br>${esc(s.joining_date||"—")}</small></div><div>${s.employee_signature_url?`<img class="id-sign" src="${esc(s.employee_signature_url)}">`:""}<small style="display:block;text-align:center">Employee Signature</small></div></div></div><div class="id-card id-back"><div class="id-top"><img class="id-logo" src="${esc(logo)}" onerror="this.src='logo.png'"><div><div class="id-company">TERMS &amp; AUTHORIZATION</div><div class="id-tag">${esc(p.company_name||"SS ENTERPRISES")}</div></div></div><div class="id-back-body"><h4>AUTHORITY STATEMENT</h4><div class="id-auth">Cardholder is authorised for the assigned ${esc(s.department||"company")} project and services. Property of ${esc(p.company_name||"SS Enterprises")}. Non-transferable.</div><h4>CONTACT INFORMATION</h4><div class="id-auth"><b>Office:</b> ${esc(p.address||"Donar Road, Darbhanga")}<br><b>Company Contact:</b> ${esc(p.phone||"")}<br><b>Employee Mobile:</b> ${esc(s.phone||"—")}</div><div class="id-back-sign"><div>${p.stamp_url?`<img class="id-stamp" src="${esc(p.stamp_url)}">`:""}<small>Company Stamp / Mohar</small></div><div>${p.signature_url?`<img class="id-authorized" src="${esc(p.signature_url)}">`:""}<small>Authorized Signatory</small></div><div><div class="id-qr id-qr-back" data-qr-url="${esc(publicEmployeeUrl(code))}"></div><small>SCAN FOR FULL ID + COMPANY DETAILS</small></div></div></div><div class="id-bottom"><small>${esc(p.company_name||"SS ENTERPRISES")} · ${esc(code)}</small><small>Joining Date: ${esc(s.joining_date||"—")}</small></div></div></div>`}
function renderIdCard(s,autoPrint=false){let box=$("idCardPreview");if(!box)return;box.hidden=false;box.innerHTML=`<div class="id-card-preview-label">Employee ID: ${esc(s.employee_code||"—")} · QR opens the employee and company profile</div>${idCardHtml(s)}<div class="id-actions"><button class="module-btn primary" id="printIdCard">Print ID Card</button><button class="module-btn ghost" id="closeIdCard">Close Preview</button></div>`;let qs=box.querySelectorAll(".id-qr");if(window.QRCode)qs.forEach(q=>{let text=q.dataset.qrUrl||publicEmployeeUrl(s.employee_code);new QRCode(q,{text,width:128,height:128,colorDark:"#061733",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.M})});if(autoPrint)setTimeout(()=>printIdCard(s),350)}
function printIdCard(s){let h=idCardHtml(s),w=window.open("","_blank");if(!w)return;let css=`@page{size:A4;margin:12mm}html,body{margin:0;padding:0;background:#fff!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}body{font-family:Arial,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}.id-sheet{display:grid;grid-template-columns:1fr 1fr;gap:7mm;align-items:start}.id-card{width:85.6mm;height:54mm;box-sizing:border-box;margin:0;background-color:#061733!important;background-image:linear-gradient(135deg,#061733 0%,#0b2e5d 65%,#17457d 100%)!important;color:#fff;border:1px solid #cda94b;-webkit-print-color-adjust:exact;print-color-adjust:exact;border-radius:4mm;overflow:hidden;position:relative}.id-card:after{content:'SS ENTERPRISES';position:absolute;inset:35% auto auto 3%;font-size:17mm;font-weight:900;letter-spacing:1mm;color:rgba(255,255,255,.035);transform:rotate(-24deg)}.id-top{display:flex;align-items:center;gap:2.5mm;padding:3.2mm 3.5mm 2.4mm;border-bottom:1px solid rgba(219,181,78,.55);position:relative;z-index:1}.id-logo{width:14mm;height:14mm;object-fit:contain;background:#fff;border-radius:2mm;padding:1mm}.id-company{font-size:4.3mm;font-weight:900;letter-spacing:.3mm}.id-tag{font-size:2.3mm;color:#d7e5f5;margin-top:1mm}.id-main{display:grid;grid-template-columns:22mm 1fr 20mm;gap:2.4mm;padding:3.2mm;position:relative;z-index:1}.id-photo{width:21mm;height:26mm;object-fit:cover;background:#eaf0f6;border:1px solid #d4b25a;border-radius:1.5mm}.id-photo-empty{display:grid;place-items:center;color:#6b7d92;font-size:2.5mm}.id-info h3{font-size:4.3mm;margin:0 0 1mm}.id-info p{font-size:2.45mm;margin:1mm 0;line-height:1.25}.id-info b,.id-back-body h4{color:#f0cf73}.id-qr{background:#fff;padding:1.3mm;border-radius:1.5mm;width:18mm;height:18mm}.id-qr canvas,.id-qr img{width:100%!important;height:100%!important}.id-project{font-size:2.25mm;color:#dce8f7;margin-top:1.4mm}.id-abha{display:inline-block;margin-top:1.4mm;padding:1mm 1.6mm;border-radius:99px;background:#0b7c65;color:#fff;font-size:2.1mm;font-weight:900}.id-bottom{display:flex;justify-content:space-between;align-items:end;padding:1.7mm 3.5mm 2.5mm;border-top:1px solid rgba(255,255,255,.14);position:absolute;left:0;right:0;bottom:0;z-index:1}.id-bottom small{font-size:2.1mm;color:#d6e1ef}.id-sign{max-width:22mm;max-height:8mm;object-fit:contain;background:#fff}.id-back-body{padding:3.5mm;position:relative;z-index:1}.id-back-body h4{margin:0 0 1.5mm;font-size:3mm}.id-auth{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:2mm;padding:2.4mm;font-size:2.45mm;line-height:1.4;margin-bottom:3mm}.id-back-sign{display:grid;grid-template-columns:1fr 1fr 1fr;gap:2mm;align-items:end;margin-top:4mm;text-align:center;font-size:2mm}.id-back-sign img{display:block;margin:auto;max-width:17mm;max-height:9mm;object-fit:contain}.id-stamp,.id-authorized{background:#fff;max-width:17mm;max-height:9mm}.id-qr-back{margin:auto}.id-actions,.id-card-preview-label{display:none}`;w.document.write(`<html><head><meta charset="utf-8"><title>SS Enterprises ID Card - ${esc(s.full_name)}</title><style>${css}</style></head><body>${h}<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>document.querySelectorAll('.id-qr').forEach(function(e){new QRCode(e,{text:e.dataset.qrUrl||${JSON.stringify(publicEmployeeUrl(s.employee_code))},width:128,height:128})});setTimeout(function(){window.print()},600)<\/script></body></html>`);w.document.close()}

function renderReports(){let active=company.staff.filter(s=>s.status==="active").length,present=company.attendance.filter(a=>a.attendance_date===today()&&a.status==="present").length,pm=company.payroll.filter(p=>(p.salary_month||"").slice(0,7)===monthNow()).reduce((a,x)=>a+Number(x.net_salary||0),0),inc=company.income.reduce((a,x)=>a+Number(x.amount||0),0),exp=company.expenses.reduce((a,x)=>a+Number(x.amount||0),0);$("reportStaff").textContent=active;$("reportPresent").textContent=present;$("reportPayroll").textContent=money(pm);$("reportNet").textContent=money(inc-exp);$("reportText").textContent=`Active staff: ${active}. Present today: ${present}. Current-month payroll: ${money(pm)}. Recorded income: ${money(inc)}. Recorded expenses: ${money(exp)}. Net recorded income/expense balance: ${money(inc-exp)}.`}

function renderCompanyProfile(){
  const p=company.profile||{};
  const set=(id,v)=>{if($(id))$(id).value=v??""};
  set("cp_name",p.company_name); set("cp_phone",p.phone); set("cp_email",p.email); set("cp_address",p.address);
  set("cp_offer_footer",p.offer_footer||"For SS Enterprises"); set("cp_joining_footer",p.joining_footer||"For SS Enterprises");
  set("cp_logo",p.logo_url); set("cp_signature",p.signature_url); set("cp_stamp",p.stamp_url);
  if($("companyLogoPreview"))$("companyLogoPreview").src=p.logo_url||"logo.png";
  if($("companySignaturePreview"))$("companySignaturePreview").src=p.signature_url||"";
  if($("companyStampPreview"))$("companyStampPreview").src=p.stamp_url||"";
  if($("companyProfileName"))$("companyProfileName").textContent=p.company_name||"SS ENTERPRISES";
}
async function uploadCompanyAsset(file,key){
  if(!file||!sb)return;
  let ext=(file.name.split(".").pop()||"png").toLowerCase().replace(/[^a-z0-9]/g,"")||"png";
  let path=`company/${key}-${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
  let r=await sb.storage.from("site-assets").upload(path,file,{upsert:false,contentType:file.type});
  if(r.error)return msg(r.error.message);
  company.profile[key]=sb.storage.from("site-assets").getPublicUrl(path).data.publicUrl;
  renderCompanyProfile();
  msg("Company asset uploaded. Press Save Company Profile.",true);
}
async function saveCompanyProfile(){
  let p=company.profile||{id:1};
  p.company_name=$("cp_name")?.value.trim()||"SS ENTERPRISES";
  p.phone=$("cp_phone")?.value.trim()||"";
  p.email=$("cp_email")?.value.trim()||"";
  p.address=$("cp_address")?.value.trim()||"Donar Road, Darbhanga";
  p.offer_footer=$("cp_offer_footer")?.value.trim()||"For SS Enterprises";
  p.joining_footer=$("cp_joining_footer")?.value.trim()||"For SS Enterprises";
  p.logo_url=$("cp_logo")?.value.trim()||"";
  p.signature_url=$("cp_signature")?.value.trim()||"";
  p.stamp_url=$("cp_stamp")?.value.trim()||"";
  let r=await sb.from("company_profile").upsert({id:1,company_name:p.company_name,address:p.address,phone:p.phone,email:p.email,logo_url:p.logo_url,signature_url:p.signature_url,stamp_url:p.stamp_url,offer_footer:p.offer_footer,joining_footer:p.joining_footer,updated_at:new Date().toISOString()});
  if(r.error)return msg("Company profile save failed: "+r.error.message);
  company.profile=p; renderCompanyProfile(); msg("Company Profile saved. Offer Letter and ID Card will use these assets.",true);
}
function renderCompany(){renderCompanyProfile();renderDashboard();renderStaff();renderAttendance();renderPayroll();renderSimpleTables();renderUsers();renderLetters();$("accountIncome").textContent=money(company.income.reduce((a,x)=>a+Number(x.amount||0),0));$("accountExpense").textContent=money(company.expenses.reduce((a,x)=>a+Number(x.amount||0),0));$("accountNet").textContent=money(company.income.reduce((a,x)=>a+Number(x.amount||0),0)-company.expenses.reduce((a,x)=>a+Number(x.amount||0),0));$("accountPayments").textContent=money(company.payments.reduce((a,x)=>a+Number(x.amount||0),0));renderReports()}
async function uploadImage(file,folder,obj,key){if(!sb)return msg("Supabase is required for photo upload.");let ext=(file.name.split(".").pop()||"jpg").toLowerCase().replace(/[^a-z0-9]/g,"")||"jpg",path=`${folder}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`,r=await sb.storage.from("site-assets").upload(path,file,{upsert:false,contentType:file.type});if(r.error)return msg(r.error.message);obj[key]=sb.storage.from("site-assets").getPublicUrl(path).data.publicUrl;msg("Photo uploaded. Press Save / Publish.",true);renderProjects();renderTeam();renderGallery()}
async function saveSite(){data.settings.address="Donar Road, Darbhanga";data.settings.contact.address="Donar Road, Darbhanga";data.projects=data.projects.map(p=>({...p,location:"Bihar"}));let r=await sb.from("site_data").upsert({id:1,content:data,updated_at:new Date().toISOString()});if(r.error)msg("Website save failed: "+r.error.message);else msg("Website changes saved and published.",true)}
async function openPanel(){$("loginBox").hidden=true;$("panel").hidden=false;try{let r=await sb.from("site_data").select("content").eq("id",1).maybeSingle();if(r.error)throw r.error;normalise(r.data?.content||DEFAULT_DATA);renderProjects();renderTeam();renderContent();renderControls();renderGallery();await loadCompany()}catch(e){msg("Could not load: "+e.message);normalise(DEFAULT_DATA);renderProjects();renderTeam();renderContent();renderControls();renderGallery()}}


function updateStaffSalaryPreview(){if(!$('sf_basic'))return;let g=['sf_basic','sf_ta','sf_da','sf_rent','sf_other'].reduce((a,id)=>a+Number($(id)?.value||0),0);$('sf_salary').value=g;if($('sf_gross_preview'))$('sf_gross_preview').textContent=money(g);if($('sf_annual_preview'))$('sf_annual_preview').textContent=money(g*12)}
document.addEventListener('input',e=>{if(e.target.matches('#sf_basic,#sf_ta,#sf_da,#sf_rent,#sf_other'))updateStaffSalaryPreview()});
function printSalarySlipByPayrollId(id){let p=company.payroll.find(x=>x.id===id);if(!p)return;let s=company.staff.find(x=>x.id===p.staff_id)||{},co=company.profile||{},gross=Number(p.basic_salary||0)+Number(p.ta_travel||0)+Number(p.da_daily||0)+Number(p.rent_allowance||0)+Number(p.other_allowance||0),h=`<div class="salary-slip"><div class="letter-head"><img src="${esc(co.logo_url||'logo.png')}" style="width:70px;height:70px;object-fit:contain"><div><h2>${esc(co.company_name||'SS ENTERPRISES')}</h2><div>${esc(co.address||'Donar Road, Darbhanga')}</div></div></div><h2>Salary Slip — ${esc(String(p.salary_month).slice(0,7))}</h2><p><b>Employee:</b> ${esc(s.full_name)} &nbsp; <b>Code:</b> ${esc(s.employee_code||'—')} &nbsp; <b>Designation:</b> ${esc(s.designation||'—')}</p><table><tr><th>Earnings</th><th>Amount</th><th>Other</th><th>Amount</th></tr><tr><td>Basic Salary</td><td>${money(p.basic_salary)}</td><td>TA / Travel</td><td>${money(p.ta_travel||0)}</td></tr><tr><td>DA / Daily</td><td>${money(p.da_daily||0)}</td><td>Rent / HRA</td><td>${money(p.rent_allowance||0)}</td></tr><tr><td>Other Allowance</td><td>${money(p.other_allowance||0)}</td><td>Overtime</td><td>${money(p.overtime||0)}</td></tr><tr><th>Gross</th><th>${money(gross+Number(p.overtime||0))}</th><th>Deductions + Advance</th><th>${money(Number(p.deduction||0)+Number(p.advance_deduction||0))}</th></tr><tr><th colspan="3">Net Salary</th><th>${money(p.net_salary)}</th></tr></table><p style="margin-top:40px;text-align:right"><b>Authorised Signatory</b></p></div>`;let w=window.open('','_blank');w.document.write(`<html><head><title>Salary Slip</title><style>body{font-family:Arial;padding:30px;background:#f5f7fa}.salary-slip{max-width:794px;margin:auto;background:#fff;padding:30px;border:1px solid #d5dfeb}.letter-head{display:flex;gap:15px;align-items:center;border-bottom:3px solid #c99b2e;padding-bottom:12px}.letter-head h2{color:#08234a}.salary-slip table{width:100%;border-collapse:collapse}.salary-slip th,.salary-slip td{border:1px solid #d8e0ea;padding:9px}.salary-slip th{background:#09264f;color:#fff}@media print{body{padding:0;background:#fff}}</style></head><body>${h}</body></html>`);w.document.close();w.focus();w.print()}

