 document.addEventListener("input",e=>{let el=e.target;if(el.matches("[data-setting]"))setPath(data.settings,el.dataset.setting,el.value);if(el.matches("[data-hi-setting]")){let [a,b]=el.dataset.hiSetting.split(".");if(!data.settings[a].hi)data.settings[a].hi={};data.settings[a].hi[b]=el.value}let pr=el.closest("[data-project-index]");if(pr&&el.matches("[data-project]")){data.projects[+pr.dataset.projectIndex][el.dataset.project]=el.value;data.projects[+pr.dataset.projectIndex].location="Bihar"}let tr=el.closest("[data-team-index]");if(tr&&el.matches("[data-team]"))data.team[+tr.dataset.teamIndex][el.dataset.team]=el.value;let rr=el.closest("[data-repeat]");if(rr&&el.matches("[data-repeat-field]"))data.settings[rr.dataset.repeat].cards[+rr.dataset.index][el.dataset.repeatField]=el.value;let sr=el.closest("[data-social-index]");if(sr&&el.matches("[data-social]"))data.settings.contact.socials[+sr.dataset.socialIndex][el.dataset.social]=el.value;let gr=el.closest("[data-gallery-index]");if(gr&&el.matches("[data-gallery]"))data.settings.gallery[+gr.dataset.galleryIndex][el.dataset.gallery]=el.value});
 document.addEventListener("change",async e=>{let el=e.target;if(el.matches("#cp_logo_file,#cp_signature_file,#cp_stamp_file")){let key=el.id==="cp_logo_file"?"logo_url":el.id==="cp_signature_file"?"signature_url":"stamp_url";await uploadCompanyAsset(el.files?.[0],key);return}if(el.matches("#sf_photo_file")){
  const file=el.files?.[0];
  if(file){
    let ext=(file.name.split(".").pop()||"jpg").toLowerCase().replace(/[^a-z0-9]/g,"")||"jpg";
    let path=`staff-photos/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
    let r=await sb.storage.from("site-assets").upload(path,file,{upsert:false,contentType:file.type});
    if(r.error)msg(r.error.message);
    else{$("sf_photo").value=sb.storage.from("site-assets").getPublicUrl(path).data.publicUrl;msg("Employee photo uploaded. Save Staff to keep it.",true)}
  }
  return;
}if(el.matches("#sf_signature_file")){let saveBtn=el.closest(".admin-card")?.querySelector(".save-staff");let s=company.staff.find(x=>x.id===saveBtn?.dataset.id);let file=el.files?.[0];if(file&&s){let ext=(file.name.split(".").pop()||"png").toLowerCase().replace(/[^a-z0-9]/g,"")||"png";let path=`staff-signatures/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;let r=await sb.storage.from("site-assets").upload(path,file,{upsert:false,contentType:file.type});if(r.error)msg(r.error.message);else{$("sf_signature").value=sb.storage.from("site-assets").getPublicUrl(path).data.publicUrl;msg("Employee signature uploaded. Save Staff to keep it.",true)}}return}if(el.matches("[data-section]"))data.settings.sections[el.dataset.section]=el.checked;if(el.matches("[data-announcement]"))data.settings.announcement[el.dataset.announcement]=el.type==="checkbox"?el.checked:el.value;if(el.matches("#featuredProject"))data.settings.featuredProjectId=el.value;let pr=el.closest("[data-project-index]"),tr=el.closest("[data-team-index]"),gr=el.closest("[data-gallery-index]"),f=el.files?.[0];if(pr&&el.matches("[data-project]")){data.projects[+pr.dataset.projectIndex][el.dataset.project]=el.value;if(el.dataset.project==="status"&&el.value==="ongoing")data.projects[+pr.dataset.projectIndex].date="Active"}if(tr&&el.matches("[data-team]"))data.team[+tr.dataset.teamIndex][el.dataset.team]=el.value;if(f&&el.classList.contains("project-upload"))await uploadImage(f,"projects",data.projects[+pr.dataset.projectIndex],"photo");if(f&&el.classList.contains("team-upload"))await uploadImage(f,"team",data.team[+tr.dataset.teamIndex],"photo");if(f&&el.classList.contains("gallery-upload"))await uploadImage(f,"gallery",data.settings.gallery[+gr.dataset.galleryIndex],"url");if(el.matches("#attendanceDate,#attendanceStaff"))renderAttendance();if(el.matches("#payrollMonth,#payrollStaff"))renderPayroll()});
 document.addEventListener("click",async e=>{let t=e.target;if(t.matches(".delete-project")){data.projects.splice(+t.closest("[data-project-index]").dataset.projectIndex,1);renderProjects();renderDashboard()}if(t.matches(".toggle-publish")){let p=data.projects[+t.closest("[data-project-index]").dataset.projectIndex];p.published=p.published===false;renderProjects()}if(t.matches(".live-project")){let p=data.projects[+t.closest("[data-project-index]").dataset.projectIndex];p.status="ongoing";p.date="Active";renderProjects()}if(t.matches(".delete-team")){data.team.splice(+t.closest("[data-team-index]").dataset.teamIndex,1);renderTeam()}if(t.matches(".delete-repeat")){let r=t.closest("[data-repeat]");data.settings[r.dataset.repeat].cards.splice(+r.dataset.index,1);renderContent()}if(t.matches(".delete-social")){data.settings.contact.socials.splice(+t.closest("[data-social-index]").dataset.socialIndex,1);renderContent()}if(t.matches(".delete-gallery")){data.settings.gallery.splice(+t.closest("[data-gallery-index]").dataset.galleryIndex,1);renderGallery()}if(t.matches(".edit-staff")){let s=company.staff.find(x=>x.id===t.dataset.id);$("staffFormBox").innerHTML=staffForm(s);$("staffFormBox").hidden=false;showTab("staff")}if(t.matches(".idcard-staff")){let s=company.staff.find(x=>x.id===t.dataset.id);if(s){showTab("letters");$("letterStaff").value=s.id;renderIdCard(s,false)}}if(t.matches(".delete-staff")){if(confirm("Delete this staff record?")){let r=await sb.from("staff").delete().eq("id",t.dataset.id);if(r.error)msg(r.error.message);else{await loadCompany();msg("Staff deleted.",true)}}}if(t.matches(".save-att"))await saveAttendance(t.dataset.staff);if(t.matches(".leave-approve")){let r=await sb.from("leaves").update({status:t.dataset.status}).eq("id",t.dataset.id);if(r.error)msg(r.error.message);else{await loadCompany();msg("Leave updated.",true)}}if(t.matches(".advance-recovered")){let r=await sb.from("staff_advances").update({status:"recovered"}).eq("id",t.dataset.id);if(r.error)msg(r.error.message);else{await loadCompany();msg("Advance marked recovered.",true)}}if(t.matches(".close-form"))t.closest(".admin-card").hidden=true;if(t.matches(".form-save-leave"))await saveForm("leave");if(t.matches(".form-save-advance"))await saveForm("advance");if(t.matches(".form-save-promotion"))await saveForm("promotion");if(t.matches(".form-save-account"))await saveForm("accounts");if(t.matches(".save-staff"))await saveStaff(t.dataset.id);if(t.matches(".delete-user")){let r=await sb.from("app_users").delete().eq("id",t.dataset.id);if(!r.error){await loadCompany();msg("Role record deleted.",true)}}});
