 $("addProject").onclick=()=>{data.projects.push({id:"p-"+Date.now(),name:"New Project",department:"Department / Client",location:"Bihar",status:"upcoming",description:"Add genuine project details.",date:"Upcoming",link:"",photo:"",published:false});renderProjects();showTab("projects")};$("addTeam").onclick=()=>{data.team.push({id:"team-"+Date.now(),role:"Designation",name:"New Member",location:"Bihar",responsibilities:"Add responsibilities.",photo:"",contact:""});renderTeam();showTab("team")};$("addAboutCard").onclick=()=>{data.settings.about.cards.push({title:"New About Item",text:"Add description."});renderContent()};$("addServiceCard").onclick=()=>{data.settings.services.cards.push({title:"New Service",text:"Add service description."});renderContent()};$("addSocial").onclick=()=>{data.settings.contact.socials.push({label:"Social",url:""});renderContent()};$("addGallery").onclick=()=>{data.settings.gallery.push({url:"",caption:""});renderGallery();showTab("gallery")};$("saveAll").onclick=saveSite;$("saveAllBottom").onclick=saveSite;$("newStaff").onclick=()=>{$("staffFormBox").innerHTML=staffForm();$("staffFormBox").hidden=false};$("staffSearch").oninput=renderStaff;$("staffStatusFilter").onchange=renderStaff;$("attendanceDate").value=today();$("payrollMonth").value=monthNow();$("markAllPresent").onclick=async()=>{let d=$("attendanceDate").value||today();for(let s of company.staff.filter(x=>x.status==="active")){let old=company.attendance.find(a=>a.staff_id===s.id&&a.attendance_date===d);old?await sb.from("attendance").update({status:"present"}).eq("id",old.id):await sb.from("attendance").insert({staff_id:s.id,attendance_date:d,status:"present"})}await loadCompany();msg("Active staff marked present.",true)};$("generatePayroll").onclick=generatePayroll;$("newLeave").onclick=()=>formBox("leave");$("newAdvance").onclick=()=>formBox("advance");$("newPromotion").onclick=()=>formBox("promotion");$("newIncome").onclick=()=>{formBox("accounts");$("accountsFormBox").dataset.mode="income"};$("newExpense").onclick=()=>{formBox("accounts");$("accountsFormBox").dataset.mode="expense"};$("newPayment").onclick=()=>{formBox("accounts");$("accountsFormBox").dataset.mode="payment"};$("newUser").onclick=()=>{$("userFormBox").innerHTML=`<div class="module-form"><label>Name<input id="us_name"></label><label>Email<input id="us_email" type="email"></label><label>Auth User ID<input id="us_auth" placeholder="Supabase Auth UUID"></label><label>Role<select id="us_role"><option>owner</option><option>admin</option><option>hr</option><option>accounts</option><option>manager</option><option>viewer</option></select></label></div><button class="module-btn primary save-user">Save Role</button>`;$("userFormBox").hidden=false};$("refreshReports").onclick=renderReports;if($("saveCompanyProfile"))$("saveCompanyProfile").onclick=saveCompanyProfile;
 // user role save and letters
 document.addEventListener("click",async e=>{if(e.target.matches(".save-user")){let r=await sb.from("app_users").insert({name:$("us_name").value,email:$("us_email").value,auth_user_id:$("us_auth").value||null,role:$("us_role").value});if(r.error)msg(r.error.message);else{await loadCompany();$("userFormBox").hidden=true;msg("Role saved.",true)}}if(e.target.matches(".print-one-slip")){printSalarySlipByPayrollId(e.target.dataset.id);return}if(e.target.matches(".transfer-salary")){await transferSalary(e.target.dataset.id);return}if(e.target.matches("#generateLetter")){selectedStaffId=$("letterStaff").value;$("letterPreview").innerHTML=letterHtml();let s=company.staff.find(x=>x.id===$("letterStaff").value);if(s)renderIdCard(s,false)}if(e.target.matches("#previewIdCard")){let s=company.staff.find(x=>x.id===$("letterStaff").value);if(s)renderIdCard(s,false);else msg("Select a staff member first.")}if(e.target.matches("#printIdCard")){let s=company.staff.find(x=>x.id===$("letterStaff").value);if(s)printIdCard(s)}if(e.target.matches("#closeIdCard")){let b=$("idCardPreview");if(b)b.hidden=true}if(e.target.matches("#printLetter")){
let h=$("letterPreview").innerHTML;
if(!h)return;
let w=window.open("","_blank");
if(!w)return;
let printCss=`@page{size:A4;margin:10mm}html,body{margin:0;padding:0;background:#fff!important}body{font-family:Georgia,'Times New Roman',serif;color:#18283f}.letter-document{max-width:none;margin:0}.letter-page{position:relative;overflow:hidden;background:#fff;border:1px solid #cbd8e8;padding:35px 42px;box-sizing:border-box;min-height:277mm;margin:0;line-height:1.55;font-size:11.5px;page-break-after:always}.letter-watermark{position:absolute;top:36%;left:8%;font-family:Arial,sans-serif;font-size:70px;font-weight:800;letter-spacing:5px;color:rgba(6,23,51,.055);transform:rotate(-28deg)}.letter-page>*{position:relative;z-index:1}.letter-head{display:flex;align-items:center;gap:12px;padding-bottom:9px;border-bottom:3px solid #c99b2e}.letter-head img{width:64px;height:64px;object-fit:contain}.letter-head h2{font-family:Arial,sans-serif;color:#08234a;letter-spacing:1px;margin:0}.letter-meta{display:flex;justify-content:space-between;margin:12px 0;font:11px Arial,sans-serif}.letter-to{background:#eef4fa;border-left:4px solid #c99b2e;padding:8px 11px;font:11px Arial,sans-serif}.letter-subject{color:#08234a;text-align:center;text-decoration:underline;text-underline-offset:5px}.letter-detail-box{background:#f4f7fb;border:1px solid #d6deea;border-radius:8px;padding:10px 14px;margin:12px 0;font:11px Arial,sans-serif}.letter-detail-box p{margin:5px 0}.letter-note{background:#fff7df;border-left:4px solid #d3a52f;padding:8px 10px}.letter-sign{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin-top:20px}.letter-sign img{max-width:110px;max-height:55px;object-fit:contain}.letter-footer{margin-top:12px;padding-top:9px;border-top:1px solid #cfd8e5;text-align:center;font:10px Arial,sans-serif;color:#607086}.salary-breakup-final{width:100%;border-collapse:collapse;margin:18px 0;font:11px Arial,sans-serif}.salary-breakup-final th,.salary-breakup-final td{padding:8px;border:1px solid #d6deea}.salary-breakup-final th{background:#09264f;color:#fff;text-align:left}.salary-breakup-final th:nth-child(n+2),.salary-breakup-final td:nth-child(n+2){text-align:right}.salary-breakup-final .salary-total th{background:#09264f;color:#fff}.annual-summary{font:11px Arial,sans-serif;color:#17385e}.two-sign{grid-template-columns:1fr 1fr}.salary-page{page-break-before:auto}`;w.document.write(`<html><head><meta charset="utf-8"><title>SS Enterprises Letter</title><link rel="stylesheet" href="${new URL("styles.css",window.location.href).href}"><style>${printCss}</style></head><body>${h}</body></html>`);
w.document.close();
setTimeout(()=>{w.focus();w.print()},500);
}if(e.target.matches("#emailLetter")){let s=company.staff.find(x=>x.id===$("letterStaff").value);if(!s?.email)return msg("Staff email is not available.");location.href=`mailto:${encodeURIComponent(s.email)}?subject=${encodeURIComponent($("letterSubject").value||"SS Enterprises Letter")}&body=${encodeURIComponent("Your letter has been generated in the SS Enterprises Admin Panel. Please contact the company if you need the PDF/document copy.")}`}if(e.target.matches("#saveLetter")){let s=company.staff.find(x=>x.id===$("letterStaff").value),h=$("letterPreview").innerHTML;if(!s||!h)return msg("Generate the letter first.");let r=await sb.from("letters").insert({staff_id:s.id,letter_type:$("letterType").value,letter_number:$("letterNumber").value,issue_date:$("letterDate").value||today(),subject:$("letterSubject").value,body_html:h,email_to:s.email});if(r.error)msg(r.error.message);else{await loadCompany();msg("Letter saved.",true)}}});
 $("letterType").onchange=()=>{if($("letterStaff").value)$("letterPreview").innerHTML=letterHtml()};$("letterStaff").onchange=()=>{$("letterPreview").innerHTML=letterHtml();let s=company.staff.find(x=>x.id===$("letterStaff").value);if(s)renderIdCard(s,false)};
 if($("loginBtn"))$("loginBtn").onclick=async()=>{if(!sb)return;let r=await sb.auth.signInWithPassword({email:$("email").value.trim(),password:$("password").value});if(r.error)$("loginMsg").textContent=r.error.message;else await openPanel()};$("logout").onclick=async()=>{await sb.auth.signOut();location.reload()};
 async function init(){if(!sb){$("setupNotice").hidden=false;$("setupNotice").innerHTML="<b>Supabase is not configured.</b> Check config.js.";return}let r=await sb.auth.getSession();if(r.data?.session)await openPanel();else $("loginBox").hidden=false}init();
